        nonlocal process, result
        try:
            process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            process.communicate()
        except Exception as e:
            result = str(e)

    process = None
    result = None
    thread = threading.Thread(target=worker)
    thread.start()
    thread.join(timeout)

